};

DeviceAddress bus6_IDs[SENSORS_PER_BUS] = {
  { 0x28, 0xD0, 0x02, 0xFB, 0x0F, 0x00, 0x00, 0xE3 }, // Sensor A11
  { 0x28, 0xEA, 0xED, 0xFA, 0x0F, 0x00, 0x00, 0xFB }, // Sensor B11
  { 0x28, 0x97, 0xC9, 0xFB, 0x0F, 0x00, 0x00, 0x41 }, // Sensor C11
  { 0x28, 0xEB, 0x06, 0xFB, 0x0F, 0x00, 0x00, 0xE9 }, // Sensor D11
  { 0x28, 0x8A, 0x8C, 0xFB, 0x0F, 0x00, 0x00, 0x6B }, // Sensor A12
  { 0x28, 0xF8, 0xD8, 0xFB, 0x0F, 0x00, 0x00, 0x17 }, // Sensor B12
  { 0x28, 0x65, 0x01, 0xFB, 0x0F, 0x00, 0x00, 0x41 }, // Sensor C12
  { 0x28, 0x04, 0x25, 0xFB, 0x0F, 0x00, 0x00, 0x52 }  // Sensor D12
};

unsigned long lastRequestTime = 0;
int currentState = 0;
const int CONVERSION_DELAY = 100; // 100ms wait for 9-bit resolution

// We will use an array to make looping through the IDs easy
DeviceAddress* all_bus_IDs[] = {bus1_IDs, bus2_IDs, bus3_IDs, bus4_IDs, bus5_IDs, bus6_IDs};

void setup() {
  Serial.begin(115200); // Crucial: Fast baud rate so serial sending doesn't cause lag

  for (int i = 0; i < NUM_BUSES; i++) {
    buses[i]->begin();
    buses[i]->setResolution(9); // Drop to 9-bit for maximum speed (94ms conversion)
    buses[i]->setWaitForConversion(false);
  }
}

void loop() {
  // --- NEW: Hardware Manager Auto-Discovery Handshake ---
  if (Serial.available() > 0) {
    String incomingData = Serial.readStringUntil('\n');
    incomingData.trim();
    if (incomingData == "?WHOAMI") {
      Serial.println("TEMP_SENSOR");
    }
  }
  // ------------------------------------------------------

  unsigned long currentMillis = millis();

  switch (currentState) {
    case 0: // STATE 0: TRIGGER MEASUREMENT
      for (int i = 0; i < NUM_BUSES; i++) {
        buses[i]->requestTemperatures();
      }
      lastRequestTime = currentMillis;
      currentState = 1; // Move to the waiting state
      break;

    case 1: // STATE 1: WAIT FOR SENSORS
      // If 100ms has passed, the sensors are done calculating
      if (currentMillis - lastRequestTime >= CONVERSION_DELAY) {
        currentState = 2; // Move to reading Bus 1
      }
      // If 100ms hasn't passed, the Arduino can run other code here!
      break;

    // STATES 2 through 7: READ AND TRANSMIT EACH BUS
    case 2:
    case 3:
    case 4:
    case 5:
    case 6:
    case 7: {
      int busIndex = currentState - 2; // Converts state 2-7 into bus index 0-5

      // Print the Bus Number first
      Serial.print(busIndex + 1);

      // Read and print all 8 sensors on this bus
      for (int i = 0; i < SENSORS_PER_BUS; i++) {
        float tempC = buses[busIndex]->getTempC(all_bus_IDs[busIndex][i]);
        Serial.print(","); // Comma separator for Python to split easily
        if (tempC <= -100.0) { // Catch disconnected sensor errors
          Serial.print("ERR");
        } else {
          Serial.print(tempC, 1); // Print with 1 decimal place to save serial bandwidth
        }
      }
      Serial.println(); // End the line, Python will read this as a complete packet

      currentState++; // Move to the next bus (or back to start)

      if (currentState > 7) {
        currentState = 0; // All buses read, restart the cycle
      }
      break;
    }
  }
}

import nidaqmx
import nidaqmx.system


def find_channels():
    system = nidaqmx.system.System.local()

    if not system.devices:
        print("No NI-DAQ devices found! Check your USB/Ethernet connection.")
        return

    print("=== Available DAQ Channels ===")
    for device in system.devices:
        print(f"\nDevice/Module Name: {device.name}")
        print("Analog Input Channels:")

        # This will list every AI channel this specific device has
        for ai_chan in device.ai_physical_chans:
            print(f"  '{ai_chan.name}'")


if __name__ == "__main__":
    find_channels()

""" Unit tests for the GUI -> logic command dispatch path.
The E-STOP button rides this path, so it must never block and never lose a STOP. These use a plain queue.Queue (same bounded semantics and same Full/Empty exceptions as multiprocessing.Queue) so no GUI or subprocess is needed. """ import queue import sys import os
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from gui_layout import send_command_nonblocking
def drain(q): out = [] while True: try: out.append(q.get_nowait()) except queue.Empty: return out
class TestNonBlockingDispatch: def test_normal_send_enqueues(self): q = queue.Queue(maxsize=10) assert send_command_nonblocking(q, "ARM") is True assert drain(q) == ["ARM"]
def test_does_not_block_when_full(self): # The original bug: .put() on a full queue blocks the GUI thread forever. # If this test hangs, the regression is back. q = queue.Queue(maxsize=3) for i in range(3): send_command_nonblocking(q, ("SET_LIMITS", i)) assert q.full()
assert send_command_nonblocking(q, "STOP") is True
def test_estop_gets_through_a_full_queue(self): q = queue.Queue(maxsize=3) for i in range(3): send_command_nonblocking(q, ("SET_LIMITS", i))
send_command_nonblocking(q, "STOP") assert "STOP" in drain(q)
def test_full_queue_drops_oldest_not_newest(self): q = queue.Queue(maxsize=3) for i in range(3): send_command_nonblocking(q, ("SET_LIMITS", i))
send_command_nonblocking(q, ("SET_LIMITS", 99)) remaining = drain(q)
assert ("SET_LIMITS", 0) not in remaining # oldest evicted assert ("SET_LIMITS", 99) in remaining # newest survived
def test_queued_estop_is_never_evicted(self): # STOP sitting at the head must survive later spinbox spam. q = queue.Queue(maxsize=3) send_command_nonblocking(q, "STOP") send_command_nonblocking(q, ("SET_LIMITS", 1)) send_command_nonblocking(q, ("SET_LIMITS", 2)) assert q.full()
# Spam more limit changes against the full queue. for i in range(10): send_command_nonblocking(q, ("SET_LIMITS", 100 + i))
assert "STOP" in drain(q)
def test_non_critical_dropped_when_it_would_evict_estop(self): q = queue.Queue(maxsize=1) send_command_nonblocking(q, "STOP")
assert send_command_nonblocking(q, ("SET_LIMITS", 1)) is False assert drain(q) == ["STOP"]
def test_estop_may_replace_a_queued_estop(self): # Redundant STOPs collapse -- same net effect, still a STOP pending. q = queue.Queue(maxsize=1) send_command_nonblocking(q, "STOP")
assert send_command_nonblocking(q, "STOP") is True assert drain(q) == ["STOP"]
def test_spinbox_spam_then_estop_still_arrives(self): # End-to-end shape of the reported hazard: rapid limit changes while the # logic process is stalled, followed by a panic E-STOP press. q = queue.Queue(maxsize=10) for i in range(200): send_command_nonblocking(q, ("SET_LIMITS", i))
assert send_command_nonblocking(q, "STOP") is True assert "STOP" in drain(q)

""" Unit tests for the DAQ layer's pure data handling.
Covers cumulative-tap differencing and temperature line parsing, both of which previously assumed a fixed 12S / 6x8 layout and would raise or silently corrupt readings on any other pack. No NI-DAQ or serial hardware required. """ import math import os import sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from hardware_manager import derive_cell_voltages, parse_temperature_line
# ================= CELL VOLTAGE DIFFERENCING =================
class TestDeriveCellVoltages: def test_uniform_pack_differences_correctly(self): # 12 taps at 4.1 V per cell -> every cell reads 4.1 V. cumulative = [4.1 * (i + 1) for i in range(12)] cells, total = derive_cell_voltages(cumulative)
assert len(cells) == 12 for v in cells: assert math.isclose(v, 4.1, abs_tol=1e-9) assert math.isclose(total, 49.2, abs_tol=1e-9)
def test_follows_input_length_not_a_fixed_count(self): # The old code hardcoded 12 and would IndexError on anything shorter. for series in [4, 12, 14, 20]: cumulative = [3.7 * (i + 1) for i in range(series)] cells, total = derive_cell_voltages(cumulative) assert len(cells) == series assert math.isclose(total, 3.7 * series, rel_tol=1e-9)
def test_detects_a_weak_cell(self): # Cell 3 is 0.5 V low; differencing must localise it. cumulative = [4.0, 8.0, 11.5, 15.5] cells, total = derive_cell_voltages(cumulative)
assert math.isclose(cells[2], 3.5, abs_tol=1e-9) assert math.isclose(total, 15.5, abs_tol=1e-9)
def test_single_cell_pack(self): cells, total = derive_cell_voltages([4.2]) assert cells == [4.2] assert math.isclose(total, 4.2)
def test_empty_input_does_not_raise(self): cells, total = derive_cell_voltages([]) assert cells == [] assert total == 0.0
# ================= TEMPERATURE LINE PARSING =================
class TestParseTemperatureLine: def test_well_formed_line(self): line = "1,25.0,25.5,26.0,26.5,27.0,27.5,28.0,28.5" parsed = parse_temperature_line(line, sensors_per_bus=8, bus_count=6)
assert parsed is not None bus_idx, readings = parsed assert bus_idx == 0 # bus numbers are 1-based on the wire assert len(readings) == 8 assert math.isclose(readings[0], 25.0) assert math.isclose(readings[7], 28.5)
def test_err_sensors_are_skipped_not_zeroed(self): # A disconnected sensor must leave the previous reading in place rather # than writing a bogus 0.0 that would drag the max-temp calculation down. line = "2,25.0,ERR,26.0,ERR,27.0,27.5,28.0,28.5" bus_idx, readings = parse_temperature_line(line, 8, 6)
assert bus_idx == 1 assert 1 not in readings assert 3 not in readings assert len(readings) == 6
def test_wrong_field_count_is_rejected(self): # Truncated serial line -- must not partially apply. assert parse_temperature_line("1,25.0,25.5", 8, 6) is None
def test_non_numeric_bus_is_rejected(self): assert parse_temperature_line("x,1,2,3,4,5,6,7,8", 8, 6) is None
def test_out_of_range_bus_is_rejected(self): # Bus 9 on a 6-bus rig would have written past the end of the array. assert parse_temperature_line("9,1,2,3,4,5,6,7,8", 8, 6) is None assert parse_temperature_line("0,1,2,3,4,5,6,7,8", 8, 6) is None
def test_garbage_temperature_field_is_skipped(self): bus_idx, readings = parse_temperature_line("1,25.0,junk,26.0,4,5,6,7,8", 8, 6) assert 1 not in readings assert math.isclose(readings[0], 25.0)
def test_adapts_to_a_different_sensor_count(self): line = "3," + ",".join(str(20.0 + i) for i in range(4)) bus_idx, readings = parse_temperature_line(line, sensors_per_bus=4, bus_count=8)
assert bus_idx == 2 assert len(readings) == 4
def test_empty_line_is_rejected(self): assert parse_temperature_line("", 8, 6) is None
def test_negative_temperatures_are_accepted(self): # The cells are rated to -40 C; sub-zero readings are legitimate. line = "1," + ",".join(["-15.5"] * 8) _, readings = parse_temperature_line(line, 8, 6) assert all(math.isclose(v, -15.5) for v in readings.values())

""" Unit tests for the rig configuration layer.
This is safety-relevant: SafetyLimits derives the over-current, over-temp and undervoltage trip points from the cell datasheet, so a wrong derivation puts wrong thresholds into the logic process. Also covers persistence, because a config that fails to round-trip silently reverts a future team's settings. """ import json import math import os import sys import tempfile
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from rig_config import ( VehicleParams, PackConfig, SafetyLimits, DaqConfig, RigConfig, field_label, )
# ================= PACK DERIVATION =================
class TestPackDerivation: def test_defaults_match_p45b_datasheet(self): # Molicel INR-21700-P45B v1.2, 12S4P. These are the numbers validated # against the datasheet -- if one drifts, the rig is mis-rated. p = PackConfig() assert p.cell_count == 48 assert math.isclose(p.capacity_ah, 18.0) # 4.5 Ah x 4P assert math.isclose(p.max_current_a, 180.0) # 45 A x 4P assert math.isclose(p.max_voltage, 50.4) # 4.2 V x 12S assert math.isclose(p.min_voltage, 30.0) # 2.5 V x 12S assert math.isclose(p.nominal_voltage, 43.2) # 3.6 V x 12S assert math.isclose(p.resistance_ohm, 0.045) # 15 mOhm / 4P x 12S
def test_parallel_count_scales_current_and_capacity_not_voltage(self): p4 = PackConfig(parallel_count=4) p6 = PackConfig(parallel_count=6)
assert math.isclose(p6.max_current_a, p4.max_current_a * 1.5) assert math.isclose(p6.capacity_ah, p4.capacity_ah * 1.5) assert math.isclose(p6.max_voltage, p4.max_voltage)
def test_series_count_scales_voltage_not_current(self): s12 = PackConfig(series_count=12) s14 = PackConfig(series_count=14)
assert math.isclose(s14.max_voltage, s12.max_voltage * 14 / 12) assert math.isclose(s14.max_current_a, s12.max_current_a)
def test_module_count_scales_battery_voltage_not_current(self): # These describe the CAR's battery. The bench loads one module only -- # they are reference figures, not anything the bank sees. p = PackConfig(modules_in_series=9) assert p.battery_cell_count == 48 * 9 assert math.isclose(p.battery_max_voltage, p.max_voltage * 9) assert math.isclose(p.battery_min_voltage, p.min_voltage * 9) assert math.isclose(p.battery_resistance_ohm, p.resistance_ohm * 9) assert math.isclose(p.battery_energy_wh, p.energy_wh * 9) # Series modules share current, so the current limit is unchanged. assert math.isclose(p.max_current_a, PackConfig(modules_in_series=1).max_current_a)
def test_single_module_battery_equals_module(self): p = PackConfig(modules_in_series=1) assert math.isclose(p.battery_max_voltage, p.max_voltage) assert p.battery_cell_count == p.cell_count
def test_internal_resistance_series_adds_parallel_divides(self): p = PackConfig(series_count=10, parallel_count=5, cell_dc_milliohm=20.0) # 20 mOhm / 5P = 4 mOhm per block, x10S = 40 mOhm assert math.isclose(p.resistance_ohm, 0.040)
def test_minimum_capacity_option_is_more_conservative(self): typical = PackConfig(use_minimum_capacity=False) minimum = PackConfig(use_minimum_capacity=True)
assert minimum.capacity_ah < typical.capacity_ah assert math.isclose(minimum.capacity_ah, 17.2) # 4.3 Ah x 4P
def test_sag_matches_ohms_law(self): p = PackConfig() assert math.isclose(p.sag_volts(180.0), 180.0 * 0.045)
def test_voltage_under_load_reproduces_the_sag_hazard(self): # A pack resting at a healthy-looking 3.2 V/cell is pushed under the # 2.5 V/cell cutoff while loaded. This is why the trip sits above 30 V. p = PackConfig() loaded = p.voltage_under_load(ocv_per_cell=3.2, current_a=187.0) assert loaded < p.min_voltage assert math.isclose(loaded / p.series_count, 2.499, abs_tol=0.001)
def test_suggested_min_voltage_is_above_absolute_cutoff(self): p = PackConfig() assert p.suggested_min_voltage() > p.min_voltage assert math.isclose(p.suggested_min_voltage(), 36.0)
# ================= LIMIT DERIVATION =================
class TestLimitDerivation: def test_derives_from_pack_by_default(self): pack = PackConfig() limits = SafetyLimits().apply_pack_derivation(pack)
# Operating limit sits a buffer below the rating so the E-STOP, which # fires at max_amps + buffer, lands exactly ON the rating. assert math.isclose(limits.max_amps, 175.0) assert math.isclose(limits.max_amps + limits.amp_buffer, pack.max_current_a) assert math.isclose(limits.max_temp, 60.0) assert math.isclose(limits.min_volts, 36.0)
def test_trip_point_never_exceeds_pack_rating(self): for buffer in [0.0, 5.0, 20.0, 100.0]: pack = PackConfig() limits = SafetyLimits(amp_buffer=buffer).apply_pack_derivation(pack) assert limits.max_amps + limits.amp_buffer <= pack.max_current_a + 1e-9
def test_absurd_buffer_cannot_drive_limit_to_zero(self): pack = PackConfig() limits = SafetyLimits(amp_buffer=500.0).apply_pack_derivation(pack) assert limits.max_amps > 0
def test_derivation_follows_a_different_cell(self): # A future team's cell: 30 A/cell, 55 C ceiling, 20S6P. pack = PackConfig(cell_max_continuous_a=30.0, cell_max_temp_c=55.0, parallel_count=6, series_count=20) limits = SafetyLimits(amp_buffer=5.0).apply_pack_derivation(pack)
assert math.isclose(limits.max_amps, 175.0) # 30 A x 6P = 180, less 5 buffer assert math.isclose(limits.max_temp, 55.0) assert math.isclose(limits.min_volts, 60.0) # 3.0 V x 20S
def test_derivation_is_skipped_when_disabled(self): pack = PackConfig() limits = SafetyLimits(derive_from_pack=False, max_amps=99.0, max_temp=42.0) limits.apply_pack_derivation(pack)
assert math.isclose(limits.max_amps, 99.0) assert math.isclose(limits.max_temp, 42.0)
def test_derate_start_kept_below_ceiling(self): # Derate range must stay positive or the ramp cannot compute. pack = PackConfig(cell_max_temp_c=50.0) limits = SafetyLimits(derate_start=55.0).apply_pack_derivation(pack) assert limits.derate_start < limits.max_temp
def test_command_dict_shape_matches_logic_process(self): # evaluate_safety indexes these directly, so a missing key is a KeyError # inside the safety-critical loop rather than a silently skipped check. keys = set(SafetyLimits().to_command_dict()) assert keys == {'max_amps', 'amp_buffer', 'max_temp', 'min_volts', 'min_cell_volts', 'cell_sense_floor', 'temp_stale_timeout', 'daq_stale_timeout', 'derate_en', 'derate_start'}
def test_per_cell_trip_derives_above_cell_cutoff(self): pack = PackConfig() limits = SafetyLimits().apply_pack_derivation(pack) assert limits.min_cell_volts > pack.cell_min_voltage
def test_per_cell_trip_below_cutoff_is_flagged(self): pack = PackConfig() limits = SafetyLimits(derive_from_pack=False, min_cell_volts=2.0, amp_buffer=0.0, max_amps=180.0, max_temp=60.0, min_volts=36.0) assert any("Per-cell trip" in w for w in limits.exceedances(pack))
def test_non_positive_stale_timeout_is_flagged(self): pack = PackConfig() limits = SafetyLimits(derive_from_pack=False, temp_stale_timeout_s=0.0, amp_buffer=0.0, max_amps=180.0, max_temp=60.0, min_volts=36.0, min_cell_volts=2.7) assert any("staleness" in w for w in limits.exceedances(pack))
# ================= DERIVATION CONFLICTS =================
class TestDerivationConflicts: """Derivation is authoritative, but must never discard an edit silently."""
def test_untouched_config_reports_nothing(self): pack = PackConfig() limits = SafetyLimits().apply_pack_derivation(pack) assert limits.derivation_conflicts(pack) == []
def test_hand_edited_limit_is_reported(self): pack = PackConfig() limits = SafetyLimits(max_amps=120.0) # engineer derates conflicts = limits.derivation_conflicts(pack)
names = {c[0] for c in conflicts} assert 'max_amps' in names loaded, derived = next((lo, d) for n, lo, d in conflicts if n == 'max_amps') assert loaded == 120.0 assert derived == 175.0
def test_reversion_can_be_in_the_unsafe_direction(self): # The reason this warning exists: a deliberate derate coming back higher. pack = PackConfig() limits = SafetyLimits(max_amps=120.0) _, loaded, derived = next(c for c in limits.derivation_conflicts(pack) if c[0] == 'max_amps') assert derived > loaded
def test_nothing_reported_when_derivation_is_off(self): pack = PackConfig() limits = SafetyLimits(derive_from_pack=False, max_amps=120.0) assert limits.derivation_conflicts(pack) == []
def test_conflicts_do_not_mutate_the_limits(self): # Probing must not apply the derivation as a side effect. pack = PackConfig() limits = SafetyLimits(max_amps=120.0) limits.derivation_conflicts(pack) assert limits.max_amps == 120.0
def test_every_derived_field_is_covered(self): # If apply_pack_derivation gains a field, DERIVED_FIELDS must too, or # that field would start reverting silently again. pack = PackConfig(series_count=14, parallel_count=6, cell_max_temp_c=55.0, cell_min_voltage=2.8) limits = SafetyLimits() before = {f: getattr(limits, f) for f in SafetyLimits.DERIVED_FIELDS} limits.apply_pack_derivation(pack)
changed = {f for f in before if abs(before[f] - getattr(limits, f)) > 1e-9} assert changed, "expected this pack to move several derived limits" assert changed <= set(SafetyLimits.DERIVED_FIELDS)
def test_load_surfaces_conflicts_on_the_config(self): raw = RigConfig.defaults().to_dict() raw['limits']['max_amps'] = 120.0 cfg = RigConfig.from_dict(raw) assert any(c[0] == 'max_amps' for c in cfg.discarded_limits)
def test_conflicts_never_reach_the_saved_file(self): raw = RigConfig.defaults().to_dict() raw['limits']['max_amps'] = 120.0 cfg = RigConfig.from_dict(raw) assert cfg.discarded_limits # present in memory assert set(cfg.to_dict()) == {'vehicle', 'pack', 'limits', 'daq'}
def test_pack_change_still_redderives(self): # The behaviour the warning must not regress: a bigger pack still moves # the limits, rather than inheriting the old pack's ceiling. raw = RigConfig.defaults().to_dict() raw['pack']['parallel_count'] = 8 cfg = RigConfig.from_dict(raw) assert math.isclose(cfg.limits.max_amps + cfg.limits.amp_buffer, 360.0)
# ================= EXCEEDANCE WARNINGS =================
class TestExceedances: def test_derived_defaults_are_clean(self): pack = PackConfig() limits = SafetyLimits().apply_pack_derivation(pack) assert limits.exceedances(pack) == []
def test_buffer_pushing_trip_over_rating_is_flagged(self): # The E-STOP fires at max_amps + buffer, so a limit exactly at the # rating still trips over it. This is the 182/187 A bug, generalised. pack = PackConfig() limits = SafetyLimits(derive_from_pack=False, max_amps=180.0, amp_buffer=5.0) warnings = limits.exceedances(pack) assert any("exceeds" in w and "A" in w for w in warnings)
def test_zero_buffer_at_rating_is_clean(self): pack = PackConfig() limits = SafetyLimits(derive_from_pack=False, max_amps=180.0, amp_buffer=0.0) assert not any("pack rating" in w for w in limits.exceedances(pack))
def test_overtemp_limit_is_flagged(self): pack = PackConfig() limits = SafetyLimits(derive_from_pack=False, max_temp=65.0, amp_buffer=0.0, max_amps=180.0, min_volts=36.0) assert any("discharge ceiling" in w for w in limits.exceedances(pack))
def test_undervoltage_below_absolute_cutoff_is_flagged(self): pack = PackConfig() limits = SafetyLimits(derive_from_pack=False, min_volts=28.0, amp_buffer=0.0, max_amps=180.0, max_temp=60.0) assert any("absolute cutoff" in w for w in limits.exceedances(pack))
def test_impossible_derate_range_is_flagged(self): pack = PackConfig() limits = SafetyLimits(derive_from_pack=False, derate_enabled=True, derate_start=60.0, max_temp=60.0, amp_buffer=0.0, max_amps=180.0, min_volts=36.0) assert any("derate" in w.lower() for w in limits.exceedances(pack))
# ================= PERSISTENCE =================
class TestPersistence: def test_round_trip_preserves_values(self): cfg = RigConfig.defaults() cfg.vehicle.mass_car_kg = 245.5 cfg.vehicle.drag_coefficient = 0.42 cfg.pack.cell_model = "Samsung INR21700-50E" cfg.pack.parallel_count = 6
with tempfile.TemporaryDirectory() as d: path = os.path.join(d, "cfg.json") cfg.save(path) loaded = RigConfig.load(path)
assert math.isclose(loaded.vehicle.mass_car_kg, 245.5) assert math.isclose(loaded.vehicle.drag_coefficient, 0.42) assert loaded.pack.cell_model == "Samsung INR21700-50E" assert loaded.pack.parallel_count == 6
def test_missing_file_falls_back_to_defaults(self): with tempfile.TemporaryDirectory() as d: loaded = RigConfig.load(os.path.join(d, "nope.json")) assert math.isclose(loaded.pack.capacity_ah, 18.0)
def test_corrupt_file_falls_back_rather_than_crashing(self): # A broken config must never stop the rig from starting. with tempfile.TemporaryDirectory() as d: path = os.path.join(d, "bad.json") with open(path, 'w') as fh: fh.write("{ this is not json") loaded = RigConfig.load(path) assert math.isclose(loaded.pack.max_current_a, 180.0)
def test_unknown_keys_are_ignored(self): # Forward compatibility: a config from a newer version still loads. raw = RigConfig.defaults().to_dict() raw['pack']['some_future_field'] = 123 raw['vehicle']['another_one'] = "x" loaded = RigConfig.from_dict(raw) assert math.isclose(loaded.pack.capacity_ah, 18.0)
def test_missing_keys_fall_back_to_field_defaults(self): loaded = RigConfig.from_dict({'pack': {'parallel_count': 8}}) assert loaded.pack.parallel_count == 8 assert math.isclose(loaded.pack.cell_max_continuous_a, 45.0) assert math.isclose(loaded.pack.max_current_a, 360.0)
def test_empty_dict_yields_defaults(self): loaded = RigConfig.from_dict({}) assert math.isclose(loaded.vehicle.total_mass_kg, 330.0)
def test_loading_redderives_limits_for_changed_pack(self): # Someone edits the JSON to a bigger pack; limits must follow, not # silently keep the old pack's current ceiling. raw = RigConfig.defaults().to_dict() raw['pack']['parallel_count'] = 8 loaded = RigConfig.from_dict(raw) assert math.isclose(loaded.limits.max_amps + loaded.limits.amp_buffer, 360.0)
def test_saved_file_is_readable_json(self): with tempfile.TemporaryDirectory() as d: path = os.path.join(d, "cfg.json") RigConfig.defaults().save(path) with open(path) as fh: raw = json.load(fh) assert set(raw) == {'vehicle', 'pack', 'limits', 'daq'}
# ================= DAQ CONFIG =================
class TestDaqConfig: def test_defaults_match_the_12s_wiring(self): d = DaqConfig() assert d.channel_count == 12 assert d.sensor_count == 48 # 6 buses x 8 sensors assert d.temp_fields_per_line == 9 # bus number + 8 readings
def test_default_wiring_validates_against_default_pack(self): assert DaqConfig().validate(PackConfig()) == []
def test_channel_count_mismatch_is_reported(self): # 12 channels wired, but the pack was reconfigured to 14S. problems = DaqConfig().validate(PackConfig(series_count=14)) assert any("voltage channels" in p for p in problems)
def test_sensor_count_mismatch_is_reported(self): # 48 thermistors cannot cover a 14S5P (70 cell) pack. problems = DaqConfig(voltage_channels=[f"ch{i}" for i in range(14)]).validate( PackConfig(series_count=14, parallel_count=5)) assert any("thermistors" in p for p in problems)
def test_current_channel_colliding_with_voltage_is_reported(self): d = DaqConfig(current_channel="cDAQ1Mod8/ai1") assert any("also listed" in p for p in d.validate(PackConfig()))
def test_duplicate_voltage_channels_are_reported(self): chans = list(DaqConfig().voltage_channels) chans[5] = chans[0] assert any("Duplicate" in p for p in DaqConfig(voltage_channels=chans).validate(PackConfig()))
def test_non_positive_sample_period_is_reported(self): assert any("Sample period" in p for p in DaqConfig(sample_period_s=0.0).validate(PackConfig()))
def test_matching_custom_wiring_validates_clean(self): # A future team's 14S5P rig, correctly wired: 14 taps, 70 thermistors. pack = PackConfig(series_count=14, parallel_count=5) daq = DaqConfig( voltage_channels=[f"cDAQ1Mod{1 + i // 4}/ai{i % 4}" for i in range(14)], temp_bus_count=10, sensors_per_bus=7, ) assert daq.validate(pack) == [] assert daq.sensor_count == pack.cell_count
def test_default_factory_does_not_share_state(self): # A mutable default would let one config's edits leak into another. a, b = DaqConfig(), DaqConfig() a.voltage_channels.append("cDAQ1Mod9/ai0") assert len(b.voltage_channels) == 12
def test_channel_list_survives_round_trip(self): cfg = RigConfig.defaults() cfg.daq.voltage_channels = ["a/ai0", "b/ai1", "c/ai2"] loaded = RigConfig.from_dict(cfg.to_dict()) assert loaded.daq.voltage_channels == ["a/ai0", "b/ai1", "c/ai2"]
def test_config_without_daq_section_gets_defaults(self): # Configs written before the DAQ section existed must still load. loaded = RigConfig.from_dict({'pack': {'series_count': 12}}) assert loaded.daq.channel_count == 12
def test_top_level_validate_covers_limits_and_daq(self): cfg = RigConfig.defaults() cfg.pack.series_count = 14 # now disagrees with the 12 channels cfg.limits.max_temp = 999.0 # and exceeds the cell rating problems = cfg.validate() assert any("voltage channels" in p for p in problems) assert any("discharge ceiling" in p for p in problems)
# ================= GUI FIELD LABELS =================
class TestFieldLabels: def test_known_field_has_label_and_unit(self): label, unit = field_label('mass_car_kg', {'mass_car_kg': ("Car mass", "kg")}) assert label == "Car mass" assert unit == "kg"
def test_unknown_field_falls_back_to_prettified_name(self): label, unit = field_label('some_new_param', {}) assert label == "Some new param" assert unit == ""

"""
Visual design system for the telemetry GUI.

One place for colour, type and spacing so the interface stays coherent as future
teams extend it. Widgets carry a `variant` property and pick up styling from the
global stylesheet rather than each carrying its own inline CSS string.

Two rules worth keeping if you change any of this:

  * Colour carries meaning. Red means a fault or a hard limit, amber means a
    warning or an armed-but-not-running state, green means healthy or active.
    Nothing decorative uses those three.
  * Live numbers render in a monospace face with tabular figures. Proportional
    digits change width as values update, so readouts jitter and are harder to
    read at a glance on a moving vehicle rig.
"""

# ================= PALETTE =================

BG            = "#0d1117"   # window background
SURFACE       = "#161b22"   # cards, panels
SURFACE_HIGH  = "#21262d"   # raised controls, inputs
SURFACE_HOVER = "#30363d"
BORDER        = "#30363d"
BORDER_SUBTLE = "#21262d"

TEXT          = "#e6edf3"
TEXT_DIM      = "#8b949e"
TEXT_MUTED    = "#6e7681"

ACCENT        = "#2f81f7"   # interactive / informational
ACCENT_HOVER  = "#4a92f8"
ACCENT_DIM    = "#1f6feb"

SUCCESS       = "#3fb950"
SUCCESS_DIM   = "#238636"
WARNING       = "#d29922"
WARNING_DIM   = "#9e6a03"
DANGER        = "#f85149"
DANGER_DIM    = "#da3633"

# Telemetry trace colours, distinguishable for the common colour-vision types.
TRACE_VOLTAGE = "#e3b341"
TRACE_CURRENT = "#39c5cf"

# Thermal map ramp. Multi-stop rather than a straight blue-to-red interpolation:
# blending those two endpoints directly passes through a muddy purple midpoint,
# and mid-range cells become impossible to rank against each other. Routing via
# teal and amber keeps every step of the ramp visually ordered.
HEAT_STOPS = [
    (0.00, "#1f6feb"),  # cool
    (0.35, "#39c5cf"),  # teal
    (0.68, "#d29922"),  # amber
    (1.00, "#f85149"),  # at limit
]
HEAT_COLD     = HEAT_STOPS[0][1]
HEAT_HOT      = HEAT_STOPS[-1][1]


# ================= TYPOGRAPHY =================

FONT_UI = '"Segoe UI", "Inter", system-ui, sans-serif'
FONT_MONO = '"Cascadia Mono", "Consolas", "DejaVu Sans Mono", monospace'

SIZE_DISPLAY = 30
SIZE_HEADING = 15
SIZE_BODY = 13
SIZE_SMALL = 12
SIZE_CAPTION = 10


# ================= SPACING =================

GAP_XS = 4
GAP_SM = 8
GAP_MD = 12
GAP_LG = 16
RADIUS = 6
RADIUS_SM = 4


def app_stylesheet() -> str:
    """Global stylesheet. Applied once to the QApplication."""
    return f"""
    QWidget {{
        background-color: {BG};
        color: {TEXT};
        font-family: {FONT_UI};
        font-size: {SIZE_BODY}px;
    }}

    QToolTip {{
        background-color: {SURFACE_HIGH};
        color: {TEXT};
        border: 1px solid {BORDER};
        padding: 6px 8px;
    }}

    /* ---------- Buttons ---------- */

    QPushButton {{
        background-color: {SURFACE_HIGH};
        color: {TEXT};
        border: 1px solid {BORDER};
        border-radius: {RADIUS}px;
        padding: 9px 16px;
        font-size: {SIZE_BODY}px;
        font-weight: 600;
    }}
    QPushButton:hover  {{ background-color: {SURFACE_HOVER}; border-color: {TEXT_MUTED}; }}
    QPushButton:pressed{{ background-color: {SURFACE}; }}
    QPushButton:disabled {{ color: {TEXT_MUTED}; border-color: {BORDER_SUBTLE}; }}

    QPushButton[variant="primary"] {{
        background-color: {ACCENT_DIM}; border-color: {ACCENT}; color: #ffffff;
    }}
    QPushButton[variant="primary"]:hover {{ background-color: {ACCENT_HOVER}; }}

    QPushButton[variant="success"] {{
        background-color: {SUCCESS_DIM}; border-color: {SUCCESS}; color: #ffffff;
    }}
    QPushButton[variant="success"]:hover {{ background-color: {SUCCESS}; }}

    QPushButton[variant="warning"] {{
        background-color: {WARNING_DIM}; border-color: {WARNING}; color: #ffffff;
    }}
    QPushButton[variant="warning"]:hover {{ background-color: {WARNING}; color: #14171c; }}

    /* The E-STOP. Deliberately the loudest control on screen -- do not tone
       this down for visual balance. */
    QPushButton[variant="danger"] {{
        background-color: {DANGER_DIM};
        border: 2px solid {DANGER};
        color: #ffffff;
        font-size: {SIZE_HEADING}px;
        font-weight: 800;
        padding: 9px 22px;
        letter-spacing: 0.5px;
    }}
    QPushButton[variant="danger"]:hover  {{ background-color: {DANGER}; }}
    QPushButton[variant="danger"]:pressed{{ background-color: #b62324; }}

    QPushButton:checked {{
        background-color: {DANGER_DIM}; border-color: {DANGER}; color: #ffffff;
    }}

    /* ---------- Inputs ---------- */

    QDoubleSpinBox, QSpinBox, QLineEdit {{
        background-color: {SURFACE_HIGH};
        color: {TEXT};
        border: 1px solid {BORDER};
        border-radius: {RADIUS_SM}px;
        padding: 5px 7px;
        font-family: {FONT_MONO};
        font-size: {SIZE_SMALL}px;
        selection-background-color: {ACCENT_DIM};
    }}
    QDoubleSpinBox:focus, QSpinBox:focus, QLineEdit:focus {{ border-color: {ACCENT}; }}
    QDoubleSpinBox:hover, QSpinBox:hover, QLineEdit:hover {{ border-color: {TEXT_MUTED}; }}

    QSpinBox::up-button, QSpinBox::down-button,
    QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {{
        background-color: {SURFACE_HOVER};
        border: none;
        width: 16px;
    }}
    QSpinBox::up-button:hover, QSpinBox::down-button:hover,
    QDoubleSpinBox::up-button:hover, QDoubleSpinBox::down-button:hover {{
        background-color: {ACCENT_DIM};
    }}

    QCheckBox {{ spacing: {GAP_SM}px; font-size: {SIZE_SMALL}px; }}
    QCheckBox::indicator {{
        width: 15px; height: 15px;
        border: 1px solid {BORDER};
        border-radius: 3px;
        background-color: {SURFACE_HIGH};
    }}
    QCheckBox::indicator:checked {{
        background-color: {ACCENT_DIM};
        border-color: {ACCENT};
        image: none;
    }}
    QCheckBox::indicator:hover {{ border-color: {ACCENT}; }}

    /* ---------- Structure ---------- */

    QLabel[variant="section"] {{
        color: {TEXT_DIM};
        font-size: {SIZE_CAPTION}px;
        font-weight: 700;
        letter-spacing: 1.2px;
        padding-bottom: {GAP_XS}px;
    }}
    QLabel[variant="caption"] {{
        color: {TEXT_MUTED};
        font-size: {SIZE_CAPTION}px;
        letter-spacing: 0.6px;
        font-weight: 600;
    }}
    QLabel[variant="mono"] {{
        font-family: {FONT_MONO};
        font-size: {SIZE_SMALL}px;
        color: {TEXT};
    }}

    QFrame[variant="card"] {{
        background-color: {SURFACE};
        border: 1px solid {BORDER_SUBTLE};
        border-radius: {RADIUS}px;
    }}
    QFrame[variant="divider"] {{
        background-color: {BORDER_SUBTLE};
        max-height: 1px;
        border: none;
    }}

    /* ---------- Tabs, scroll, dialogs ---------- */

    QTabWidget::pane {{
        border: 1px solid {BORDER};
        border-radius: {RADIUS}px;
        top: -1px;
        background-color: {SURFACE};
    }}
    QTabBar::tab {{
        background-color: transparent;
        color: {TEXT_DIM};
        padding: 9px 18px;
        border: 1px solid transparent;
        border-top-left-radius: {RADIUS}px;
        border-top-right-radius: {RADIUS}px;
        font-weight: 600;
    }}
    QTabBar::tab:selected {{
        background-color: {SURFACE};
        color: {TEXT};
        border-color: {BORDER};
        border-bottom-color: {SURFACE};
    }}
    QTabBar::tab:hover:!selected {{ color: {TEXT}; }}

    QScrollArea {{ border: none; background-color: transparent; }}
    QScrollBar:vertical {{
        background: transparent; width: 10px; margin: 0;
    }}
    QScrollBar::handle:vertical {{
        background: {SURFACE_HOVER}; border-radius: 5px; min-height: 30px;
    }}
    QScrollBar::handle:vertical:hover {{ background: {TEXT_MUTED}; }}
    QScrollBar::add-line, QScrollBar::sub-line {{ height: 0; }}
    QScrollBar::add-page, QScrollBar::sub-page {{ background: none; }}

    QDialog {{ background-color: {BG}; }}
    QMessageBox {{ background-color: {SURFACE}; }}
    QMessageBox QLabel {{ color: {TEXT}; }}
    """


# ================= DYNAMIC STYLING HELPERS =================

def restyle(widget, variant):
    """Change a widget's variant and force Qt to re-apply the stylesheet.

    Qt only evaluates property selectors at polish time, so a property changed
    after construction needs an explicit unpolish/polish to take effect.
    """
    if widget.property("variant") == variant:
        return
    widget.setProperty("variant", variant)
    widget.style().unpolish(widget)
    widget.style().polish(widget)


# Foreground / background / border for each FSM state. Keyed by the state string
# the logic process emits.
FSM_COLOURS = {
    "DISCONNECTED": (TEXT_MUTED, SURFACE, BORDER),
    "IDLE":         (TEXT, SURFACE, BORDER),
    "ARMED":        ("#14171c", WARNING, WARNING),
    "RUNNING":      ("#0d1117", SUCCESS, SUCCESS),
    "FAULT":        ("#ffffff", DANGER_DIM, DANGER),
}


def fsm_style(state):
    """Inline style for the state banner. Unknown states fall back to neutral."""
    fg, bg, border = FSM_COLOURS.get(state, FSM_COLOURS["DISCONNECTED"])
    return (
        f"color: {fg}; background-color: {bg}; border: 2px solid {border}; "
        f"border-radius: {RADIUS}px; font-family: {FONT_UI}; "
        f"font-size: 22px; font-weight: 800; letter-spacing: 2px; padding: 10px 14px;"
    )


def pill_style(online):
    """Connection status pill."""
    if online:
        fg, bg, border = SUCCESS, "rgba(63, 185, 80, 0.12)", SUCCESS_DIM
    else:
        fg, bg, border = TEXT_MUTED, "transparent", BORDER
    return (
        f"color: {fg}; background-color: {bg}; border: 1px solid {border}; "
        f"border-radius: 10px; padding: 4px 12px; font-size: {SIZE_CAPTION}px; "
        f"font-weight: 700; letter-spacing: 0.6px;"
    )


def _hex_to_rgb(value):
    return int(value[1:3], 16), int(value[3:5], 16), int(value[5:7], 16)


def heat_colour(temp_c, max_safe_temp, min_temp=20.0):
    """Map a temperature onto the thermal ramp.

    Returns (hex colour, ratio) where ratio is 0.0 at min_temp and 1.0 at the
    safe limit. Interpolates across HEAT_STOPS so the ramp stays perceptually
    ordered from cool through to at-limit.
    """
    span = max(1e-6, max_safe_temp - min_temp)
    ratio = max(0.0, min(1.0, (temp_c - min_temp) / span))

    for (lo_pos, lo_hex), (hi_pos, hi_hex) in zip(HEAT_STOPS, HEAT_STOPS[1:]):
        if ratio <= hi_pos or hi_pos == 1.0:
            local = 0.0 if hi_pos == lo_pos else (ratio - lo_pos) / (hi_pos - lo_pos)
            local = max(0.0, min(1.0, local))
            lo, hi = _hex_to_rgb(lo_hex), _hex_to_rgb(hi_hex)
            r, g, b = (int(a + (z - a) * local) for a, z in zip(lo, hi))
            return f"#{r:02x}{g:02x}{b:02x}", ratio

    return HEAT_HOT, ratio


def delta_v_style(delta_v, warn=0.15, crit=0.30):
    """Cell imbalance readout. Escalates through healthy / warning / critical."""
    if delta_v > crit:
        fg, bg, border = "#ffffff", DANGER_DIM, DANGER
    elif delta_v > warn:
        fg, bg, border = "#14171c", WARNING, WARNING
    else:
        fg, bg, border = SUCCESS, SURFACE, BORDER_SUBTLE
    return (
        f"color: {fg}; background-color: {bg}; border: 1px solid {border}; "
        f"border-radius: {RADIUS_SM}px; padding: 7px; font-family: {FONT_MONO}; "
        f"font-size: {SIZE_HEADING}px; font-weight: 700;"
    )
